-- ROLLBACK patch jadwal Oktober 2026 — Pizza Snack Play
-- Dibuat otomatis dari snapshot baris produksi sebelum patch (2026-09-27).
--
-- Mengembalikan 34 baris kelas 1 & 2 ke nilai aslinya, menghapus 98 baris
-- baru, serta menghapus 20 menu + 40 menu_item yang ditambahkan patch.
-- Jalankan dengan:
--   ./node_modules/.bin/wrangler.exe d1 execute pizza-snack-play --remote \
--       --file=scripts/sql/2026-10-october-rollback.sql

-- 1. Hapus baris yang DITAMBAHKAN patch (semua baris Oktober di luar 34 id asli).
DELETE FROM schedules
 WHERE schedule_date >= '2026-10-01'
   AND id NOT IN (259, 260, 261, 262, 263, 264, 265, 266, 267, 268, 269, 270, 271, 272, 273, 274, 275, 276, 277, 278, 279, 280, 281, 282, 283, 284, 285, 286, 287, 288, 289, 290, 291, 292);

